const listTransferDiscrepancies = `-- name: ListTransferDiscrepancies :many
SELECT d.id, d.transfer_id, d.transfer_item_id, d.expected_quantity, d.received_quantity, d.difference_quantity, d.reason, d.supporting_evidence_url, d.status, d.assigned_reviewer_id, d.resolution_notes, d.resolved_at, d.created_at, d.updated_at,
       t.reference as transfer_reference,
       t.source_location_id,
       t.destination_location_id,
       ti.item_id,
       src.name as source_location_name,
       dst.name as destination_location_name,
       i.name as item_name,
       i.sku as item_sku,
       u_rev.display_name as reviewer_name
FROM transfer_discrepancies d
JOIN material_transfers t ON d.transfer_id = t.id
JOIN storage_locations src ON t.source_location_id = src.id
JOIN storage_locations dst ON t.destination_location_id = dst.id
JOIN material_transfer_items ti ON d.transfer_item_id = ti.id
JOIN inventory_items i ON ti.item_id = i.id
LEFT JOIN users u_rev ON d.assigned_reviewer_id = u_rev.id
WHERE ($1::text IS NULL OR $1 = '' OR d.status = $1)
  AND ($2::text IS NULL OR $2 = '' OR d.transfer_id = $2)
ORDER BY d.created_at DESC
`

type ListTransferDiscrepanciesParams struct {
	Column1 string `json:"column_1"`
	Column2 string `json:"column_2"`
}

type ListTransferDiscrepanciesRow struct {
	ID                      string             `json:"id"`
	TransferID              string             `json:"transfer_id"`
	TransferItemID          string             `json:"transfer_item_id"`
	ExpectedQuantity        int64              `json:"expected_quantity"`
	ReceivedQuantity        int64              `json:"received_quantity"`
	DifferenceQuantity      int64              `json:"difference_quantity"`
	Reason                  string             `json:"reason"`
	SupportingEvidenceUrl   pgtype.Text        `json:"supporting_evidence_url"`
	Status                  string             `json:"status"`
	AssignedReviewerID      pgtype.Text        `json:"assigned_reviewer_id"`
	ResolutionNotes         pgtype.Text        `json:"resolution_notes"`
	ResolvedAt              pgtype.Timestamptz `json:"resolved_at"`
	CreatedAt               pgtype.Timestamptz `json:"created_at"`
	UpdatedAt               pgtype.Timestamptz `json:"updated_at"`
	TransferReference       string             `json:"transfer_reference"`
	SourceLocationID        string             `json:"source_location_id"`
	DestinationLocationID   string             `json:"destination_location_id"`
	ItemID                  string             `json:"item_id"`
	SourceLocationName      string             `json:"source_location_name"`
	DestinationLocationName string             `json:"destination_location_name"`
	ItemName                string             `json:"item_name"`
	ItemSku                 string             `json:"item_sku"`
	ReviewerName            pgtype.Text        `json:"reviewer_name"`
}

func (q *Queries) ListTransferDiscrepancies(ctx context.Context, arg ListTransferDiscrepanciesParams) ([]ListTransferDiscrepanciesRow, error) {
	rows, err := q.db.Query(ctx, listTransferDiscrepancies, arg.Column1, arg.Column2)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListTransferDiscrepanciesRow
	for rows.Next() {
		var i ListTransferDiscrepanciesRow
		if err := rows.Scan(
			&i.ID,
			&i.TransferID,
			&i.TransferItemID,
			&i.ExpectedQuantity,
			&i.ReceivedQuantity,
			&i.DifferenceQuantity,
			&i.Reason,
			&i.SupportingEvidenceUrl,
			&i.Status,
			&i.AssignedReviewerID,
			&i.ResolutionNotes,
			&i.ResolvedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.TransferReference,
			&i.SourceLocationID,
			&i.DestinationLocationID,
			&i.ItemID,
			&i.SourceLocationName,
			&i.DestinationLocationName,
			&i.ItemName,
			&i.ItemSku,
			&i.ReviewerName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

